pub type NonEmptyStr = Str
  invariant: this.len() > 0;

fn greet(name: &NonEmptyStr) {
  io.println("Hello, " + name + "!");
}

fn first_char(s: &NonEmptyStr) -> Char
  ensures: result == s[0];
{
  return s[0];
}

fn main() -> Int {
  let name: NonEmptyStr = "Kilo";
  greet(&name);
  let c = first_char(&name);
  return c as Int;
}
